import requests

url = "https://api.example.com/v1/assemblies"

payload = {
    "object": "assembly",
    "id": "string",
    "shipTo": {
        "line1": "string",
        "country": "string"
    },
    "parts": [
        {
            "sku": "string",
            "fastener": { "kind": "screw" }
        }
    ]
}
headers = {
    "accept": "application/json",
    "content-type": "application/json"
}

response = requests.post(url, json=payload, headers=headers)

print(response.text)

